// Create text file - check if AI content exists or trigger S1 generation
const reportData = $input.first().json;

console.log('=== CREATING SECTION 1 TEXT FILE ===');
console.log('Report data received:', reportData);

const companyName = reportData.company_name || 'Unknown_Company';
const companyId = reportData.company_id || 'unknown_id';
const status = reportData.status || 'unknown';
const createdAt = reportData.created_at || new Date().toISOString();
const reportDate = new Date().toISOString().split('T')[0];

// Check if we have AI-generated content
if (!reportData.introduction_engagement_context || status === 'pending_ai_generation') {
  console.log('⚠️ No AI-generated content found - S1 subworkflow needs to run first');
  console.log('Creating status file to indicate AI generation is needed');

  const statusContent = `Due Diligence Report - Section 1: Status
${'='.repeat(80)}

Company: ${companyName}
Company ID: ${companyId}
Generated: ${reportDate}
Status: AI Generation Required

${'='.repeat(80)}

STATUS: WAITING FOR AI GENERATION

The S1 subworkflow needs to run to generate Section 1 content.
This file will be updated once the AI agent completes the analysis.

Next Steps:
1. S1 subworkflow will analyze company data
2. AI agent will generate professional Section 1 content
3. Content will be saved to database
4. This file will be replaced with actual AI-generated content

${'='.repeat(80)}
End of Status Update
Generated by Action Labs Due Diligence System
`;

  const fileName = `${companyName.replace(/[^a-zA-Z0-9]/g, '_')}_Section1_STATUS_${reportDate}.txt`;

  console.log(`✅ Created status file: ${fileName}`);

  return [{
    json: {
      company_id: companyId,
      company_name: companyName,
      file_name: fileName,
      content: statusContent,
      content_length: statusContent.length,
      created_at: reportDate,
      status: 'status_file_created',
      source: 'waiting_for_ai'
    },
    binary: {
      data: {
        data: Buffer.from(statusContent, 'utf8').toString('base64'),
        mimeType: 'text/plain',
        fileName: fileName
      }
    }
  }];
}

// We have AI-generated content
const aiGeneratedContent = reportData.introduction_engagement_context;

console.log(`✅ Found AI-generated content for: ${companyName}`);
console.log(`Content length: ${aiGeneratedContent.length} characters`);
console.log(`Status: ${status}`);

// Create text file with AI-generated content
const textFileContent = `Due Diligence Report - Section 1: Introduction & Engagement Context
${'='.repeat(80)}

Company: ${companyName}
Company ID: ${companyId}
Generated: ${reportDate}
AI Generated: ${createdAt}
Status: ${status}
Source: S1 Subworkflow (AI Agent Generated)

${'='.repeat(80)}

${aiGeneratedContent}

${'='.repeat(80)}
End of Section 1
Generated by Action Labs Due Diligence System
AI Content Generated by S1 Subworkflow
`;

const fileName = `${companyName.replace(/[^a-zA-Z0-9]/g, '_')}_Section1_AI_Generated_${reportDate}.txt`;

console.log(`✅ Created AI-generated text file: ${fileName}`);
console.log(`File contains AI-generated content from S1 subworkflow`);
console.log(`Total file length: ${textFileContent.length} characters`);

// Return data in Code node format (array of items)
return [{
  json: {
    company_id: companyId,
    company_name: companyName,
    file_name: fileName,
    content: textFileContent,
    content_length: textFileContent.length,
    ai_content_length: aiGeneratedContent.length,
    created_at: reportDate,
    status: 'ai_content_ready',
    source: 's1_subworkflow'
  },
  binary: {
    data: {
      data: Buffer.from(textFileContent, 'utf8').toString('base64'),
      mimeType: 'text/plain',
      fileName: fileName
    }
  }
}];
